Bool ExperienceTracker::gainExpForLevel(
	Int levelsToGain,
	Bool canScaleForBonus,
	Bool provideFeedback)
{
	const Int levelCount = levelsToGain;
	if (levelCount <= 0)
		return false;

	Bool gainedLevel = false;
	Int i = 0;
	while (i < levelCount)
	{
		Int experience = TheExperienceLevelSystem->
			bfmeExperienceForNextLevel(m_parent, 0);
		if (experience <= 0)
			break;
		addExperiencePoints(
			experience,
			false,
			false,
			canScaleForBonus,
			provideFeedback);
		++i;
		gainedLevel = true;
	}

	return gainedLevel;
}

void ExperienceTracker::addExperiencePoints(
	Real experienceGain,
	Bool canScaleForBonus,
	Bool isShared,
	volatile Bool allowLevelGain,
	Bool provideFeedback)
{
	ExperienceTracker *tracker = this;
	GameLogic *gameLogic = TheBfmeGameLogic;
	ObjectID sinkId = tracker->m_experienceSink;
	while (sinkId != OBJECT_ID_INVALID)
	{
		sinkId = tracker->m_experienceSink;
		Object *sink = ((BFMEObjectLookup *)gameLogic)->findObjectByID(
			sinkId);
		if (sink == 0)
			break;
		experienceGain *= tracker->m_experienceScalar;
		allowLevelGain = true;
		tracker = sink->m_experienceTracker;
		sinkId = tracker->m_experienceSink;
	}

	const ThingTemplate *thingTemplate = tracker->m_parent->getTemplate();
	if (thingTemplate == 0 || !thingTemplate->isTrainable())
		return;

	Real adjustedExperience = experienceGain;
	if (!isShared)
	{
		adjustedExperience *= tracker->m_experienceScalar;
		if (((GameLogicShim *)gameLogic)->unidentified_0001e0ab())
		{
			const Int playerIndex =
				((Rva002EE330PlayerListThunk *)Rva002EE330ThePlayers)->
					unidentified_000389f6(false);
			Gen_00083240 *scales = (Gen_00083240 *)
				((char *)TheWritableGlobalData + 0xee0);
			if (tracker->m_parent->isKindOf((KindOfType)7))
				adjustedExperience *= scales->bfmeGet100(playerIndex);
			else
				adjustedExperience *= scales->bfmeGet80(playerIndex);
		}
	}

	if (canScaleForBonus)
		adjustedExperience = tracker->bfmeScaleLivingWorldExperience(
			adjustedExperience);

	tracker->m_currentExperience += adjustedExperience;

